#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package MQTTnet@4.3.2.930 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable using System; using System.Text; using System.Threading; using System.Threading.Tasks; using MQTTnet; using MQTTnet.Client; using MQTTnet.Server;  namespace MQTTNetDemo {     /// <summary>     /// MQTT演示程序 - 完整版 (同时包含服务器和客户端)     /// </summary>     public class Program     {         private static readonly ManualResetEventSlim _exitEvent = new ManualResetEventSlim(false);                  public static async Task Main(string[] args)         {             Console.WriteLine("MQTTnet Complete Demo Starting...");             Console.WriteLine("====================================\n");              try             {                 // 启动MQTT服务器                 var serverTask = RunMqttServer();                                  // 等待服务器启动                 await Task.Delay(1000);                                  // 启动MQTT客户端                 var clientTask = RunMqttClient();                                  // 等待任一任务完成                 await Task.WhenAny(serverTask, clientTask);                                  // 等待用户输入退出                 Console.WriteLine("\n\nDemo completed. Press any key to exit...");                 Console.ReadKey();                                  // 触发退出事件                 _exitEvent.Set();                                  // 等待所有任务完成                 await Task.WhenAll(serverTask, clientTask);             }             catch (Exception ex)             {                 Console.WriteLine($"Error: {ex.Message}");                 Console.WriteLine($"Stack trace: {ex.StackTrace}");                 Console.ReadKey();             }         }                  /// <summary>         /// 运行MQTT服务器         /// </summary>         private static async Task RunMqttServer()         {             Console.WriteLine("Starting MQTT Server...");                          try             {                 // 创建MQTT工厂                 var factory = new MqttFactory();                                  // 配置服务器选项                 var serverOptions = new MqttServerOptions();                                  // 创建服务器                 var server = factory.CreateMqttServer(serverOptions);                                  // 启动服务器                 await server.StartAsync();                 Console.WriteLine("✅ MQTT Server started on port 1883");                                  // 等待退出信号                 _exitEvent.Wait();                                  // 停止服务器                 await server.StopAsync();                 Console.WriteLine("📤 MQTT Server stopped");             }             catch (Exception ex)             {                 Console.WriteLine($"❌ Server Error: {ex.Message}");             }         }                  /// <summary>         /// 运行MQTT客户端         /// </summary>         private static async Task RunMqttClient()         {             Console.WriteLine("\nStarting MQTT Client...");                          try             {                 // 创建MQTT工厂                 var factory = new MqttFactory();                                  // 创建MQTT客户端                 var client = factory.CreateMqttClient();                                  // 配置客户端选项                 var clientOptions = new MqttClientOptions                 {                     ChannelOptions = new MqttClientTcpOptions                     {                         Server = "127.0.0.1",                         Port = 1883                     },                     ClientId = "DemoClient",                     CleanSession = true                 };                                  // 连接到服务器                 await client.ConnectAsync(clientOptions);                 Console.WriteLine("✅ Client connected to MQTT server");                                  // 订阅主题                 await client.SubscribeAsync("demo/topic");                 Console.WriteLine("📩 Client subscribed to topic 'demo/topic'");                                  // 设置消息接收回调                 client.ApplicationMessageReceivedAsync += e =>                 {                     var topic = e.ApplicationMessage.Topic;                     var payload = Encoding.UTF8.GetString(e.ApplicationMessage.Payload);                     Console.WriteLine($"📨 Client received message: Topic={topic}, Payload={payload}");                     return Task.CompletedTask;                 };                                  // 发布测试消息                 for (int i = 1; i <= 3; i++)                 {                     var message = new MqttApplicationMessage                     {                         Topic = "demo/topic",                         Payload = Encoding.UTF8.GetBytes($"Hello from MQTT client! (Message #{i})")                     };                                          await client.PublishAsync(message);                     Console.WriteLine($"📤 Client published message #{i}: 'Hello from MQTT client!'");                                          // 等待1秒                     await Task.Delay(1000);                 }                                  // 等待退出信号                 _exitEvent.Wait();                                  // 断开连接                 await client.DisconnectAsync();                 Console.WriteLine("📤 Client disconnected from MQTT server");             }             catch (Exception ex)             {                 Console.WriteLine($"❌ Client Error: {ex.Message}");                 Console.WriteLine($"Stack trace: {ex.StackTrace}");             }         }     } }
